const TabsContext = createContext(null);

function Tabs({ children }) {
  const [active, setActive] = useState(0);
  return (
    <TabsContext.Provider value={{ active, setActive }}>
      <div style={{ fontFamily: 'system-ui' }}>{children}</div>
    </TabsContext.Provider>
  );
}

function TabList({ children }) {
  return <div style={{ display: 'flex', gap: 8 }}>{children}</div>;
}

function Tab({ index, children }) {
  const { active, setActive } = useContext(TabsContext);
  const on = active === index;
  return (
    <button onClick={() => setActive(index)} style={{ padding: '6px 12px', fontWeight: on ? 700 : 400, borderBottom: on ? '2px solid #2563eb' : '2px solid transparent' }}>{children}</button>
  );
}

function Panel({ index, children }) {
  const { active } = useContext(TabsContext);
  if (active !== index) return null;
  return <div style={{ padding: 12 }}>{children}</div>;
}

function App() {
  return (
    <Tabs>
      <TabList>
        <Tab index={0}>Profile</Tab>
        <Tab index={1}>Settings</Tab>
      </TabList>
      <Panel index={0}>Your profile details.</Panel>
      <Panel index={1}>App settings here.</Panel>
    </Tabs>
  );
}

