const AccordionContext = createContext(null);

function Accordion({ children }) {
  const [openIndex, setOpenIndex] = useState(null);
  const toggle = (i) => setOpenIndex(cur => (cur === i ? null : i));
  return (
    <AccordionContext.Provider value={{ openIndex, toggle }}>
      <div style={{ fontFamily: 'system-ui', maxWidth: 360 }}>{children}</div>
    </AccordionContext.Provider>
  );
}

function Item({ index, title, children }) {
  const { openIndex, toggle } = useContext(AccordionContext);
  const open = openIndex === index;
  const panelId = 'acc-panel-' + index;
  const btnId = 'acc-btn-' + index;
  return (
    <div style={{ borderBottom: '1px solid #ddd' }}>
      <button id={btnId} aria-expanded={open} aria-controls={panelId} onClick={() => toggle(index)} style={{ width: '100%', textAlign: 'left', padding: 10 }}>{title}</button>
      <div id={panelId} role="region" aria-labelledby={btnId} hidden={!open} style={{ padding: open ? 10 : 0 }}>{open ? children : null}</div>
    </div>
  );
}

function App() {
  return (
    <Accordion>
      <Item index={0} title="Shipping">Ships in 3 days.</Item>
      <Item index={1} title="Returns">30-day returns.</Item>
    </Accordion>
  );
}
